import { analyzeTraces } from './feeedFeatures.js';

// Computes FEEED features off the main thread, so long logs don't freeze the page.
// Receives already-parsed traces (DOMParser, needed to read XES, is unavailable in workers).
self.onmessage = ({ data }) => {
  try {
    self.postMessage(analyzeTraces(data.traces, data.featureSet));
  } catch (e) {
    self.postMessage({ error: String(e.message || e) });
  }
};
