/**
 * The FEEED 2.2.0 features that are not (yet) in the collection's table: trace_diversity,
 * distinct_activities, repetitions, comparison_based, dfg_based and time_based, plus the
 * remaining members of the groups computed in feeedFeatures.js. Each follows FEEED's
 * definition, including its quirks, so the values match the Python library.
 */
import * as m from './statsMath.js';

const PAIRWISE_LIMIT = 400;
const SET_GROUP_LIMIT = 3000;
const SEP = '\u0001';

const finite = (x) => (Number.isFinite(x) ? x : null);

const PAIRWISE_CELL_LIMIT = 2e9;

function toIds(sequences) {
  const ids = new Map();
  return sequences.map((seq) =>
    Int32Array.from(seq, (x) => {
      let id = ids.get(x);
      if (id === undefined) {
        id = ids.size;
        ids.set(x, id);
      }
      return id;
    })
  );
}

function levenshtein(a, b) {
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  let prev = new Int32Array(b.length + 1);
  let curr = new Int32Array(b.length + 1);
  for (let j = 0; j <= b.length; j += 1) prev[j] = j;
  for (let i = 1; i <= a.length; i += 1) {
    curr[0] = i;
    const ai = a[i - 1];
    for (let j = 1; j <= b.length; j += 1) {
      const sub = prev[j - 1] + (ai === b[j - 1] ? 0 : 1);
      const del = prev[j] + 1;
      const ins = curr[j - 1] + 1;
      curr[j] = sub < del ? (sub < ins ? sub : ins) : del < ins ? del : ins;
    }
    [prev, curr] = [curr, prev];
  }
  return prev[b.length];
}

function pairwiseDistances(sequences) {
  const n = sequences.length;
  if (n < 2 || n > PAIRWISE_LIMIT) return null;
  let cells = 0;
  for (let i = 0; i < n; i += 1) {
    for (let j = i + 1; j < n; j += 1) cells += sequences[i].length * sequences[j].length;
  }
  if (cells > PAIRWISE_CELL_LIMIT) return null;
  const ints = toIds(sequences);
  const pairs = [];
  for (let i = 0; i < n; i += 1) {
    for (let j = i + 1; j < n; j += 1) pairs.push({ i, j, d: levenshtein(ints[i], ints[j]) });
  }
  return pairs;
}

function averagePairwiseDistance(pairs, n) {
  if (!pairs) return null;
  return (2 * m.sum(pairs.map((p) => p.d))) / (n * (n - 1));
}

function similarityRateVariants(pairs, variants) {
  if (!pairs) return null;
  if (variants.some((v) => v.length === 0)) return null;
  const n = variants.length;
  const total = m.sum(pairs.map(({ i, j, d }) => 1 - d / Math.max(variants[i].length, variants[j].length)));
  return (2 * total) / (n * (n - 1));
}

function traceVariantExtras(traces, lengths, variants, variantPairs) {
  const counts = new Map();
  traces.forEach((t) => {
    const key = JSON.stringify([t.caseId, t.attributes, t.events.map((e) => e.attributes)]);
    counts.set(key, (counts.get(key) || 0) + 1);
  });
  const sorted = [...counts.values()].sort((a, b) => a - b);
  const threshold = 0.8 * traces.length;
  let covered = 0;
  let coverage = 0;
  for (const c of sorted) {
    if (covered >= threshold) break;
    covered += c;
    coverage += 1;
  }
  const nVariants = variants.length;
  return {
    coverage_variants: coverage,
    rel_coverage_variants: coverage / nVariants,
    heterogeneity_rate_variants: finite(Math.log(nVariants) / Math.log(traces.length)),
    similarity_rate_variants: similarityRateVariants(variantPairs, variants),
  };
}

function distinctActivities(seqs, variants, nUniqueActivities, similarityRate, variantPairs) {
  const sets = seqs.map((s) => new Set(s));
  const sizes = sets.map((s) => s.size);
  const meanSize = m.mean(sizes);
  const meanLength = m.mean(seqs.map((s) => s.length));

  const groups = new Map();
  sets.forEach((s) => {
    const key = [...s].sort().join(SEP);
    const g = groups.get(key);
    if (g) g.count += 1;
    else groups.set(key, { set: s, count: 1 });
  });
  let nonOverlap = null;
  if (groups.size <= SET_GROUP_LIMIT) {
    const list = [...groups.values()];
    let overlap = 0;
    let undefinedPair = false;
    for (let i = 0; i < list.length && !undefinedPair; i += 1) {
      for (let j = 0; j < list.length; j += 1) {
        const a = list[i].set;
        const b = list[j].set;
        let inter = 0;
        a.forEach((x) => {
          if (b.has(x)) inter += 1;
        });
        const union = a.size + b.size - inter;
        if (union === 0) {
          undefinedPair = true;
          break;
        }
        overlap += list[i].count * list[j].count * (inter / union);
      }
    }
    if (!undefinedPair) nonOverlap = 1 - overlap / seqs.length ** 2;
  }

  const eventDensity = meanSize / meanLength;
  const complexity =
    similarityRate === null ? null : Math.log(variants.length) ** (1 - similarityRate + eventDensity) * meanSize;

  return {
    distinct_activities: {
      distinct_activities_min: m.min(sizes),
      distinct_activities_max: m.max(sizes),
      distinct_activities_mean: meanSize,
      distinct_activities_std: m.std(sizes),
      event_density: finite(eventDensity),
      distinct_activities_non_overlap: nonOverlap,
      complexity_factor: complexity === null ? null : finite(complexity),
    },
    trace_diversity: {
      simple_trace_diversity: finite(1 - meanSize / nUniqueActivities),
      advanced_trace_diversity: (() => {
        const d = averagePairwiseDistance(variantPairs, variants.length);
        return d === null ? null : finite(d / meanLength);
      })(),
    },
  };
}

function repetitions(seqs) {
  const loops = seqs.map((seq) => {
    const sizes = [];
    let i = 0;
    while (i < seq.length) {
      let peek = 0;
      while (i + peek + 1 < seq.length && seq[i + peek + 1] === seq[i]) peek += 1;
      if (peek > 0) sizes.push(peek);
      i += peek + 1;
    }
    return sizes;
  });
  const hasRepetition = seqs.map((seq) => {
    const window = [];
    for (const event of seq) {
      const position = window.lastIndexOf(event);
      if (position === -1 || position === window.length - 1) {
        window.push(event);
      } else {
        return true;
      }
    }
    return false;
  });
  const n = seqs.length;
  const withLoop = loops.filter((l) => l.length > 0).length;
  const allSizes = loops.flat();
  const withRepetition = hasRepetition.filter(Boolean).length;
  return {
    n_traces_with_loop: withLoop,
    avg_traces_with_loop: withLoop / n,
    avg_loops_per_trace: m.sum(loops.map((l) => l.length)) / n,
    max_loops_per_trace: Math.max(0, ...loops.map((l) => l.length)),
    avg_loop_size_per_trace: withLoop === 0 ? 0 : m.sum(allSizes) / withLoop,
    max_loop_size_per_trace: allSizes.reduce((a, b) => Math.max(a, b), 0),
    n_traces_with_repetition: withRepetition,
    avg_traces_with_repetition: withRepetition / n,
  };
}

function lempelZivComplexity(sequence) {
  const root = new Map();
  let phrases = 0;
  let index = 0;
  while (index < sequence.length) {
    let node = root;
    let length = 0;
    while (index + length < sequence.length && node.has(sequence[index + length])) {
      node = node.get(sequence[index + length]);
      length += 1;
    }
    if (index + length >= sequence.length) break;
    node.set(sequence[index + length], new Map());
    phrases += 1;
    index += length + 1;
  }
  return phrases;
}

function eventKey(e) {
  const entries = Object.entries(e.attributes).map(([k, v]) => [k, k === 'time:timestamp' ? e.timeMicros : v]);
  entries.sort((a, b) => (a[0] < b[0] ? -1 : 1));
  return JSON.stringify(entries);
}

function comparisonBased(traces, seqs, nVariants) {
  const pairsOf = (seq) => seq.slice(1).map((a, i) => seq[i] + SEP + a);
  const successions = new Set();
  seqs.forEach((seq) => pairsOf(seq).forEach((p) => successions.add(p)));

  const relation = new Map();
  const get = (a, b) => relation.get(a + SEP + b) || '#';
  const set = (a, b, r) => relation.set(a + SEP + b, r);
  seqs.forEach((seq) => {
    for (let i = 1; i < seq.length; i += 1) {
      const e1 = seq[i - 1];
      const e2 = seq[i];
      if (e1 === e2) set(e1, e2, '||');
      else if (get(e1, e2) === '<-') {
        set(e1, e2, '||');
        set(e2, e1, '||');
      } else if (get(e1, e2) === '#') {
        set(e1, e2, '->');
        set(e2, e1, '<-');
      }
    }
  });
  const ties = [...relation.values()].filter((r) => r === '->').length;

  const n = seqs.length;
  let affinity = null;
  if (n >= 2) {
    const groups = new Map();
    seqs.forEach((seq) => {
      const s = new Set(pairsOf(seq));
      const key = [...s].sort().join('\u0002');
      const g = groups.get(key);
      if (g) g.count += 1;
      else groups.set(key, { set: s, count: 1 });
    });
    if (groups.size <= SET_GROUP_LIMIT) {
      const list = [...groups.values()];
      let total = 0;
      for (let i = 0; i < list.length; i += 1) {
        const { set: a, count: ca } = list[i];
        if (a.size > 0) total += (ca * (ca - 1)) / 2;
        for (let j = i + 1; j < list.length; j += 1) {
          const { set: b, count: cb } = list[j];
          let inter = 0;
          a.forEach((x) => {
            if (b.has(x)) inter += 1;
          });
          const union = a.size + b.size - inter;
          if (union > 0) total += ca * cb * (inter / union);
        }
      }
      affinity = (2 * total) / (n * (n - 1));
    }
  }

  const activities = new Set(seqs.flat());
  const freq = new Map();
  let totalPairs = 0;
  seqs.forEach((seq) => {
    pairsOf(seq).forEach((p) => {
      freq.set(p, (freq.get(p) || 0) + 1);
      totalPairs += 1;
    });
  });
  let deviation = null;
  if (totalPairs > 0) {
    const random = totalPairs / activities.size ** 2;
    let sq = 0;
    freq.forEach((f) => {
      sq += (Math.abs(f - random) / totalPairs) ** 2;
    });
    sq += (activities.size ** 2 - freq.size) * (random / totalPairs) ** 2;
    deviation = 1 - Math.sqrt(sq);
  }

  let editDistance = null;
  if (n >= 2 && n <= PAIRWISE_LIMIT) {
    const keyed = traces.map((t) => t.events.map(eventKey));
    editDistance = averagePairwiseDistance(pairwiseDistances(keyed), n);
  }

  return {
    number_of_successions: successions.size,
    number_of_ties: ties,
    structure: 1 - ties / nVariants ** 2,
    average_affinity: affinity,
    lempel_ziv_complexity: lempelZivComplexity(seqs.flat()),
    deviation_from_random: deviation,
    average_edit_distance: editDistance,
  };
}

function articulationPoints(nodes, neighbours) {
  const index = new Map();
  const low = new Map();
  const points = new Set();
  let counter = 0;
  nodes.forEach((root) => {
    if (index.has(root)) return;
    index.set(root, counter);
    low.set(root, counter);
    counter += 1;
    let rootChildren = 0;
    const stack = [{ node: root, parent: null, it: [...neighbours.get(root)][Symbol.iterator]() }];
    while (stack.length) {
      const frame = stack[stack.length - 1];
      const step = frame.it.next();
      if (step.done) {
        stack.pop();
        if (stack.length) {
          const parent = stack[stack.length - 1].node;
          low.set(parent, Math.min(low.get(parent), low.get(frame.node)));
          if (parent !== root && low.get(frame.node) >= index.get(parent)) points.add(parent);
        }
        continue;
      }
      const next = step.value;
      if (next === frame.parent) continue;
      if (index.has(next)) {
        low.set(frame.node, Math.min(low.get(frame.node), index.get(next)));
      } else {
        index.set(next, counter);
        low.set(next, counter);
        counter += 1;
        if (frame.node === root) rootChildren += 1;
        stack.push({ node: next, parent: frame.node, it: [...neighbours.get(next)][Symbol.iterator]() });
      }
    }
    if (rootChildren > 1) points.add(root);
  });
  return points.size;
}

function stronglyConnectedNodesOnCycles(nodes, successors) {
  const index = new Map();
  const low = new Map();
  const onStack = new Set();
  const stack = [];
  const onCycles = new Set();
  let counter = 0;
  nodes.forEach((start) => {
    if (index.has(start)) return;
    const work = [{ node: start, it: [...successors.get(start)][Symbol.iterator]() }];
    index.set(start, counter);
    low.set(start, counter);
    counter += 1;
    stack.push(start);
    onStack.add(start);
    while (work.length) {
      const frame = work[work.length - 1];
      const step = frame.it.next();
      if (!step.done) {
        const next = step.value;
        if (!index.has(next)) {
          index.set(next, counter);
          low.set(next, counter);
          counter += 1;
          stack.push(next);
          onStack.add(next);
          work.push({ node: next, it: [...successors.get(next)][Symbol.iterator]() });
        } else if (onStack.has(next)) {
          low.set(frame.node, Math.min(low.get(frame.node), index.get(next)));
        }
        continue;
      }
      work.pop();
      if (work.length) {
        const parent = work[work.length - 1].node;
        low.set(parent, Math.min(low.get(parent), low.get(frame.node)));
      }
      if (low.get(frame.node) === index.get(frame.node)) {
        const component = [];
        let v;
        do {
          v = stack.pop();
          onStack.delete(v);
          component.push(v);
        } while (v !== frame.node);
        if (component.length > 1) component.forEach((c) => onCycles.add(c));
      }
    }
  });
  return onCycles.size;
}

function dfgBased(seqs) {
  const nodes = new Set(['START', 'END', ...seqs.flat()]);
  const successors = new Map([...nodes].map((n) => [n, new Set()]));
  const predecessors = new Map([...nodes].map((n) => [n, new Set()]));
  const addEdge = (a, b) => {
    successors.get(a).add(b);
    predecessors.get(b).add(a);
  };
  seqs.forEach((seq) => {
    if (seq.length === 0) {
      addEdge('START', 'END');
      return;
    }
    addEdge('START', seq[0]);
    for (let i = 0; i + 1 < seq.length; i += 1) addEdge(seq[i], seq[i + 1]);
    addEdge(seq[seq.length - 1], 'END');
  });
  const N = nodes.size;
  const edges = [...successors].flatMap(([a, out]) => [...out].map((b) => [a, b]));
  const E = edges.length;
  const degree = (n) => successors.get(n).size + predecessors.get(n).size;
  const degrees = [...nodes].map(degree);

  const undirected = new Map([...nodes].map((n) => [n, new Set()]));
  edges.forEach(([a, b]) => {
    if (a === b) return;
    undirected.get(a).add(b);
    undirected.get(b).add(a);
  });
  const cuts = articulationPoints([...nodes], undirected);

  const sequential = new Set([...nodes].filter((n) => predecessors.get(n).size < 2 && successors.get(n).size < 2));
  const sequentialArcs = edges.filter(([a, b]) => sequential.has(a) && sequential.has(b)).length;

  return {
    n_nodes_dfg: N,
    n_edges_dfg: E,
    coeff_of_connectivity_dfg: E / N,
    avg_node_degree_dfg: m.sum(degrees) / N,
    max_node_degree_dfg: Math.max(...degrees),
    density_dfg: E / (N * (N - 1)),
    structure_dfg: 1 - E / N ** 2,
    cyclomatic_number_dfg: E - N + 1,
    n_cut_vertices_dfg: cuts,
    separability_ratio_dfg: cuts / N,
    sequentiality_ratio_dfg: sequentialArcs / N,
    cyclicity_dfg: stronglyConnectedNodesOnCycles([...nodes], successors) / N,
  };
}

const TIME_STATS = [
  'min', 'max', 'mean', 'median', 'mode', 'std', 'variance', 'q1', 'q3', 'iqr',
  'geometric_mean', 'geometric_std', 'harmonic_mean', 'skewness', 'kurtosis',
  'coefficient_variation', 'entropy', 'skewness_hist', 'kurtosis_hist',
];
export const TIME_FEATURES = ['accumulated_time', 'execution_time', 'remaining_time', 'within_day'];

function percentileSorted(sorted, p) {
  const rank = (p / 100) * (sorted.length - 1);
  const lo = Math.floor(rank);
  const hi = Math.ceil(rank);
  return lo === hi ? sorted[lo] : sorted[lo] + (sorted[hi] - sorted[lo]) * (rank - lo);
}

function timeStats(values) {
  const sorted = Float64Array.from(values).sort();
  const plusOne = values.map((v) => v + 1);
  const hist = m.histogramDensity10(values);
  const q1 = percentileSorted(sorted, 25);
  const q3 = percentileSorted(sorted, 75);
  return {
    min: sorted[0],
    max: sorted[sorted.length - 1],
    mean: m.mean(values),
    median: percentileSorted(sorted, 50),
    mode: m.mode(values),
    std: m.std(values),
    variance: m.variance(values),
    q1,
    q3,
    iqr: q3 - q1,
    geometric_mean: m.gmean(plusOne),
    geometric_std: m.gstd(plusOne),
    harmonic_mean: m.hmean(values),
    skewness: m.skew(values),
    kurtosis: m.kurtosis(values),
    coefficient_variation: m.variation(values),
    entropy: m.entropyOfWeights(values),
    skewness_hist: m.skew(hist),
    kurtosis_hist: m.kurtosis(hist),
  };
}

function emptyTimeFeatures() {
  return Object.fromEntries(TIME_FEATURES.flatMap((f) => TIME_STATS.map((s) => [`${f}_${s}`, null])));
}

function timeBased(traces) {
  const events = traces
    .flatMap((t) => t.events.map((e) => ({ caseId: t.caseId, time: e.timeMicros })))
    .filter((e) => e.time !== null && e.time !== undefined);
  if (events.length === 0) return emptyTimeFeatures();
  const byCase = new Map();
  events.forEach((e) => {
    const list = byCase.get(e.caseId);
    if (list) list.push(e.time);
    else byCase.set(e.caseId, [e.time]);
  });
  const execution = [];
  const accumulated = [];
  const remaining = [];
  byCase.forEach((times) => {
    times.sort((a, b) => a - b);
    const first = times[0];
    const last = times[times.length - 1];
    times.forEach((t, i) => {
      execution.push(i === 0 ? 0 : (t - times[i - 1]) / 1e6);
      accumulated.push((t - first) / 1e6);
      remaining.push((last - t) / 1e6);
    });
  });
  const day = 86400e6;
  const withinDay = events.map((e) => (((e.time % day) + day) % day) / 1e6);
  const values = { accumulated_time: accumulated, execution_time: execution, remaining_time: remaining, within_day: withinDay };
  const out = {};
  TIME_FEATURES.forEach((f) => {
    const stats = timeStats(values[f]);
    TIME_STATS.forEach((s) => {
      out[`${f}_${s}`] = finite(stats[s]);
    });
  });
  return out;
}

export function computeExtraFeatures(traces, { lempelZivFlattened, prefixFlattened, globalBlockFlattened, nUniqueActivities, nUniqueStartActivities, nUniqueEndActivities, defaultOnly = false }) {
  const seqs = traces.map((t) => t.events.map((e) => e.activity));
  const lengths = seqs.map((s) => s.length);
  const variantIndex = new Map();
  seqs.forEach((s) => {
    const key = s.join(SEP);
    if (!variantIndex.has(key)) variantIndex.set(key, s);
  });
  const variants = [...variantIndex.values()];
  const hist = m.histogramDensity10(lengths);
  const variantPairs = pairwiseDistances(variants);
  const variantExtras = traceVariantExtras(traces, lengths, variants, variantPairs);
  const defaultExtras = {
    n_events: m.sum(lengths),
    ...Object.fromEntries(hist.map((v, i) => [`trace_len_hist${i + 1}`, finite(v)])),
    ...variantExtras,
    rel_unique_start_activities: nUniqueStartActivities / variants.length,
    rel_unique_end_activities: nUniqueEndActivities / variants.length,
    eventropy_global_block_flattened: globalBlockFlattened,
    eventropy_lempel_ziv_flattened: lempelZivFlattened,
    eventropy_prefix_flattened: prefixFlattened,
  };
  if (defaultOnly) return defaultExtras;
  const { distinct_activities: distinct, trace_diversity: diversity } = distinctActivities(
    seqs,
    variants,
    nUniqueActivities,
    variantExtras.similarity_rate_variants,
    variantPairs
  );

  return {
    ...defaultExtras,
    ...diversity,
    ...distinct,
    ...repetitions(seqs),
    ...comparisonBased(traces, seqs, variants.length),
    ...dfgBased(seqs),
    ...timeBased(traces),
  };
}
